import { z } from "zod";

const httpMethodSchema = z.enum(["GET", "POST"], { message: "Method must be either GET or POST" });

const newTabTargetOptionsSchema = z.object({
  method: httpMethodSchema,
});

const widgetTargetOptionsSchema = z.object({
